@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewThemeClass => Theme switch
    {
        "Dark" => "appearance-preview-dark",
        _ => ""
    };

    private string PreviewStyle => Theme switch
    {
        "Dark" => "background-color:#1e1e2e;color:#cdd6f4;",
        "System" => "background-color:#f0f0f0;color:#333;border-left:4px solid #6c757d !important;",
        _ => "background-color:#ffffff;color:#212529;"
    };

    private string PreviewFontStyle => FontSize switch
    {
        "Small" => "font-size:0.8rem;",
        "Large" => "font-size:1.2rem;",
        _ => "font-size:1rem;"
    };

    private string PreviewButtonStyle => Theme switch
    {
        "Dark" => "background-color:#89b4fa;color:#1e1e2e;border:none;" + PreviewFontStyle,
        _ => "background-color:#1b6ec2;color:white;border:none;" + PreviewFontStyle
    };

    private string PreviewBadgeStyle => Theme switch
    {
        "Dark" => "background-color:#45475a;color:#cdd6f4;",
        _ => "background-color:#e9ecef;color:#495057;"
    };

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = Task.Delay(3000).ContinueWith(_ => { ShowSuccess = false; InvokeAsync(StateHasChanged); });
    }
}

