    @if (Security is not null)
    {
        <ChangePasswordPanel OnChangePassword="OnChangePassword" />

        <div class="card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <div class="small text-muted">Add an extra layer of security to your account</div>
                </div>
                <div class="d-flex align-items-center gap-2">
                    <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <div class="form-check form-switch mb-0">
                        <input class="form-check-input" type="checkbox" checked="@TwoFactorEnabled"
                               @onchange="e => TwoFactorEnabled = (bool)(e.Value ?? false)" />
                    </div>
                </div>
            </div>
        </div>

        @if (Security.LastPasswordChange.HasValue)
        {
            <p class="text-muted small">
                Last password change: @Security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
            </p>
        }

        <h5 class="mt-4 mb-3">Active Sessions</h5>
        <div class="table-responsive">
            <table class="table table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Security.Sessions)
                    {
                        var isCurrent = session.Id == Security.Sessions.FirstOrDefault()?.Id;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-info ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (!isCurrent)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => ShowRevokeDialog(session)">
                                        Revoke
                                    </button>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <RevokeSessionDialog Visible="_showRevokeDialog"
                             SessionId="@_revokeSession?.Id"
                             Device="@_revokeSession?.Device"
                             Location="@_revokeSession?.Location"
                             OnConfirm="ConfirmRevoke"
                             OnCancel="CancelRevoke" />
    }
</div>

@code {
    [Parameter] public SecuritySettings? Security { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled;
    private bool _initialized;
    private bool _showRevokeDialog;
    private ActiveSession? _revokeSession;

    protected override void OnParametersSet()
    {
        if (Security is not null && !_initialized)
        {
            TwoFactorEnabled = Security.TwoFactorEnabled;
            _initialized = true;
        }
    }

    private void ShowRevokeDialog(ActiveSession session)
    {
        _revokeSession = session;
        _showRevokeDialog = true;
    }

    private async Task ConfirmRevoke(string sessionId)
    {
        _showRevokeDialog = false;
        await OnRevokeSession.InvokeAsync(sessionId);
    }

    private void CancelRevoke()
    {
        _showRevokeDialog = false;
        _revokeSession = null;
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}
