@using sv_d80bf5b29bcf4b1998e8ce01a870df96.Services

<div class="settings-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (Settings is not null)
    {
        <div class="row">
            <div class="col-md-6">
                <div class="mb-4">
                    <h6>Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme"
                                   id="@($"theme-{theme}")" value="@theme"
                                   checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6>Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize"
                                   id="@($"fs-{size}")" value="@size"
                                   checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6>Language</h6>
                    <select class="form-select" @bind="Language">
                        @foreach (var lang in Languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode"
                               checked="@CompactMode"
                               @onchange="e => CompactMode = (bool)(e.Value ?? false)" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@IsSaving">
                    @if (IsSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>

                @if (ShowSuccess)
                {
                    <div class="alert alert-success mt-3 py-2">✅ Appearance saved!</div>
                }
            </div>

            <div class="col-md-6">
                <h6>Live Preview</h6>
                <div class="appearance-preview border rounded p-3 @PreviewThemeClass"
                     style="@PreviewStyle">
                    <div class="@(CompactMode ? "mb-1" : "mb-3")">
                        <strong style="@PreviewFontStyle">Settings Dashboard</strong>
                    </div>
                    <p style="@PreviewFontStyle" class="@(CompactMode ? "mb-1" : "mb-2")">
                        This is a preview of how your content will look with the selected appearance settings.
                    </p>
                    <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-2")">
                        <span class="badge" style="@PreviewBadgeStyle">Badge</span>
                        <span class="badge" style="@PreviewBadgeStyle">@Language</span>
                    </div>
                    <button class="btn btn-sm" style="@PreviewButtonStyle" disabled>
                        Sample Button
                    </button>
                    <div class="mt-2 small" style="@PreviewFontStyle">
                        <em>Theme: @Theme · Font: @FontSize · Compact: @(CompactMode ? "On" : "Off")</em>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme = "Light";
    private string FontSize = "Medium";
    private string Language = "English";
    private bool CompactMode;
    private bool IsSaving;
    private bool ShowSuccess;
    private bool _initialized;

    private static readonly string[] Languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string PreviewThemeClass => Theme switch
    {
        "Dark" => "appearance-preview-dark",
        _ => ""
    };

    private string PreviewStyle => Theme switch
    {
        "Dark" => "background-color:#1e1e2e;color:#cdd6f4;",
        "System" => "background-color:#f0f0f0;color:#333;border-left:4px solid #6c757d !important;",
        _ => "background-color:#ffffff;color:#212529;"
    };

    private string PreviewFontStyle => FontSize switch
    {
        "Small" => "font-size:0.8rem;",
        "Large" => "font-size:1.2rem;",
        _ => "font-size:1rem;"
    };

    private string PreviewButtonStyle => Theme switch
    {
        "Dark" => "background-color:#89b4fa;color:#1e1e2e;border:none;" + PreviewFontStyle,
        _ => "background-color:#1b6ec2;color:white;border:none;" + PreviewFontStyle
    };

    private string PreviewBadgeStyle => Theme switch
    {
        "Dark" => "background-color:#45475a;color:#cdd6f4;",
        _ => "background-color:#e9ecef;color:#495057;"
    };

    private async Task SaveAsync()
    {
        IsSaving = true;
        ShowSuccess = false;
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
        IsSaving = false;
        ShowSuccess = true;
        _ = Task.Delay(3000).ContinueWith(_ => { ShowSuccess = false; InvokeAsync(StateHasChanged); });
    }
}

